meta.customCss:
.nav-wrapper .secondary-button{background: #fff;
  border: 1px solid rgb(154, 160, 166);
  color: rgb(95, 99, 104);
  float: none;
  margin: 0;
  padding: 8px 16px;}
.icon{background-repeat: no-repeat;
  background-size: 100%;}
.bad-clock button,
.captive-portal button,
.https-only button,
.insecure-form button,
.lookalike-url button,
.main-frame-blocked button,
.neterror button,
.pdf button,
.ssl button,
.enterprise-block button,
.enterprise-warn button,
.managed-profile-required button,
.safe-browsing-billing button,
.supervised-user-verify button,
.supervised-user-verify-subframe button{background: rgb(26, 115, 232);}
.secondary-button:active{border-color: white;
  box-shadow: 0 1px 2px 0 rgba(60, 64, 67, .3),
      0 2px 6px 2px rgba(60, 64, 67, .15);}
.secondary-button:hover{background: rgb(248, 249, 250);
  border-color: rgb(128, 134, 139);
  text-decoration: none;}
.error-code{color: rgb(95, 99, 104);
  font-size: .8em;
  margin-top: 12px;
  text-transform: uppercase;}
.icon{height: 72px;
  margin: 0 0 40px;
  width: 72px;}
.interstitial-wrapper{box-sizing: border-box;
  font-size: 1em;
  line-height: 1.6em;
  margin: 14vh auto 0;
  max-width: 600px;
  width: 100%;}
#enhanced-protection-message .icon{height: 1.5em;
  vertical-align: middle;
  width: 1.5em;}
.nav-wrapper{margin-top: 51px;}
.nav-wrapper::after{clear: both;
  content: '';
  display: table;
  width: 100%;}
.small-link{color: rgb(95, 99, 104);
  font-size: .875em;}
.interstitial-wrapper{max-width: 736px;}
button.small-link{color: rgb(26, 115, 232);}
button,
  [dir='rtl'] button,
  button.small-link,
  .nav-wrapper .secondary-button{font-family: Roboto-Regular,Helvetica;
    font-size: .933em;
    margin: 6px 0;
    transform: translatez(0);}
.nav-wrapper{box-sizing: border-box;
    padding-bottom: 8px;
    width: 100%;}
.icon{margin-bottom: 5.69vh;}
.interstitial-wrapper{box-sizing: border-box;
    margin: 7vh auto 12px;
    padding: 0 24px;
    position: relative;}
.interstitial-wrapper p{font-size: .95em;
    line-height: 1.61em;
    margin-top: 8px;}
.small-link{border: 0;}
.suggested-left > #control-buttons,
  .suggested-right > #control-buttons{float: none;
    margin: 0;}
.nav-wrapper{flex: 0 1 auto;
    margin-top: 8px;
    order: 1;
    padding-inline-end: 0;
    padding-inline-start: 0;
    position: relative;
    width: 100%;}
button,
  .nav-wrapper .secondary-button{padding: 16px 24px;}
button.small-link{color: rgb(26, 115, 232);}
.icon{-webkit-user-select: none;
  display: inline-block;}
.icon-generic{/* Can't access chrome://theme/IDR_ERROR_NETWORK_GENERIC from an untrusted
   * renderer process, so embed the resource manually. */
  content: image-set(
      url(data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEgAAABIAQMAAABvIyEEAAAABlBMVEUAAABTU1OoaSf/AAAAAXRSTlMAQObYZgAAAENJREFUeF7tzbEJACEQRNGBLeAasBCza2lLEGx0CxFGG9hBMDDxRy/72O9FMnIFapGylsu1fgoBdkXfUHLrQgdfrlJN1BdYBjQQm3UAAAAASUVORK5CYII=) 1x,
      url(data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAJAAAACQAQMAAADdiHD7AAAABlBMVEUAAABTU1OoaSf/AAAAAXRSTlMAQObYZgAAAFJJREFUeF7t0cENgDAMQ9FwYgxG6WjpaIzCCAxQxVggFuDiCvlLOeRdHR9yzjncHVoq3npu+wQUrUuJHylSTmBaespJyJQoObUeyxDQb3bEm5Au81c0pSCD8HYAAAAASUVORK5CYII=) 2x);}
.icon-info{content: image-set(
      url(data:image/png;base64,) 1x,
      url(data:image/png;base64,) 2x);}
.icon-offline{content: image-set(
      url(data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAEgAAABIAQMAAABvIyEEAAAABlBMVEUAAABTU1OoaSf/AAAAAXRSTlMAQObYZgAAAGxJREFUeF7tyMEJwkAQRuFf5ipMKxYQiJ3Z2nSwrWwBA0+DQZcdxEOueaePp9+dQZFB7GpUcURSVU66yVNFj6LFICatThZB6r/ko/pbRpUgilY0Cbw5sNmb9txGXUKyuH7eV25x39DtJXUNPQGJtWFV+BT/QAAAAABJRU5ErkJggg==) 1x,
      url(data:image/png;base64,) 2x);
  position: relative;}
.icon-disabled{content: image-set(
      url(data:image/png;base64,) 1x,
      url(data:image/png;base64,) 2x);
  width: 112px;}
.secondary-button{background: #d9d9d9;
  color: #696969;
  margin-inline-end: 16px;}
#sub-frame-error .icon-generic{margin: 0 0 16px;}
/* Styles for platform dependent separation of controls and details button. */
.suggested-left > #control-buttons,
.suggested-right > #details-button{float: left;}
.suggested-right > #control-buttons,
.suggested-left > #details-button{float: right;}
.suggested-left .secondary-button{margin-inline-end: 0;
  margin-inline-start: 16px;}
/* Offline page */
html[dir='rtl'] .runner-container,
html[dir='rtl'].offline .icon-offline{transform: scaleX(-1);}
.offline .interstitial-wrapper{color: rgb(95, 99, 104);
  font-size: 1em;
  line-height: 1.55;
  margin: 0 auto;
  max-width: 600px;
  padding-top: 100px;
  position: relative;
  width: 100%;}
.arcade-mode .interstitial-wrapper{height: 100vh;
  max-width: 100%;
  overflow: hidden;}
